fn check_age(age: u32) -> Result<u32, String> {
    if age < 18 {
        Err(String::from("too young"))
    } else {
        Ok(age)
    }
}

fn main() {
    match check_age(15) {
        Ok(a) => println!("welcome, age {a}"),
        Err(e) => println!("error: {e}"),
    }
}
